import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    index = 1

    results = []

    for _ in range(n):
        a = int(data[index])
        b = float(data[index + 1])
        op = data[index + 2]
        c = float(data[index + 3])
        index += 4

        if op == '+':
            result = a + b + c
        elif op == '-':
            result = a - b + c
        elif op == '*':
            result = a * b + c
        elif op == '/':
            if b == 0:
                result = c
            else:
                result = a / b + c
        else:
            result = c

        results.append("{:.2f}".format(result))

    for res in results:
        print(res)

if __name__ == "__main__":
    main()
